const API_URL = process.env.NEXT_PUBLIC_API_URL || "http://localhost:8080";
const TENANT_ID = process.env.NEXT_PUBLIC_TENANT_ID || "demo-tenant";

export interface OverviewStats {
  total_input_tokens: number;
  total_output_tokens: number;
  total_saved: number;
  savings_pct: number;
  event_count: number;
  top_commands: CommandStat[];
}

export interface CommandStat {
  command: string;
  saved: number;
  count: number;
}

export interface ProjectSummary {
  project_dir: string;
  total_saved: number;
  total_input: number;
  event_count: number;
  savings_pct: number;
  last_event_at: string;
}

export interface ProjectDailyStat {
  day: string;
  total_saved: number;
  total_input: number;
  event_count: number;
}

export interface ProjectStats {
  project_dir: string;
  summary: ProjectSummary;
  daily: ProjectDailyStat[];
  top_filters: CommandStat[];
}

export interface DailySavings {
  day: string;
  total_saved: number;
  total_input: number;
  event_count: number;
  compression_saved: number;
  dedup_saved: number;
}

async function apiFetch<T>(path: string): Promise<T> {
  const res = await fetch(`${API_URL}${path}`, {
    cache: "no-store",
    headers: {
      "X-Tenant-ID": TENANT_ID,
    },
  });
  if (!res.ok) {
    throw new Error(`API error: ${res.status}`);
  }
  return res.json();
}

export function fetchOverview(): Promise<OverviewStats> {
  return apiFetch("/v1/overview");
}

export function fetchProjects(): Promise<ProjectSummary[]> {
  return apiFetch("/v1/projects");
}

export function fetchProjectStats(projectDir: string): Promise<ProjectStats> {
  const normalized = projectDir.replaceAll("\\", "/");
  const encoded = normalized.replaceAll("/", "|");
  return apiFetch(`/v1/projects/${encodeURIComponent(encoded)}/stats`);
}

export function fetchSavingsTrend(days: number = 30): Promise<DailySavings[]> {
  return apiFetch(`/v1/savings/trend?days=${days}`);
}

export function formatTokens(n: number): string {
  if (n >= 1_000_000) return `${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1_000) return `${(n / 1_000).toFixed(1)}K`;
  return n.toString();
}

export function estimateCost(tokens: number): string {
  const costPer1k = 0.003;
  const cost = (tokens / 1000) * costPer1k;
  if (cost < 0.01) return "<$0.01";
  return `$${cost.toFixed(2)}`;
}

export interface WasteReport {
  pattern_type: string;
  command: string;
  total_wasted: number;
  occurrences: number;
  session_count: number;
  suggestion: string;
}

export interface ProjectWasteScore {
  project_dir: string;
  total_wasted: number;
  total_input: number;
  waste_pct: number;
  pattern_count: number;
}

export function fetchWasteReport(days: number = 30): Promise<WasteReport[]> {
  return apiFetch(`/v1/waste?days=${days}`);
}

export function fetchProjectWasteScores(
  days: number = 30
): Promise<ProjectWasteScore[]> {
  return apiFetch(`/v1/waste/projects?days=${days}`);
}

export interface SecurityAlert {
  finding_type: string;
  severity: string;
  action: string;
  command: string;
  redacted_preview: string;
  detected_at: string;
  count: number;
}

export function fetchSecurityAlerts(
  days: number = 30
): Promise<SecurityAlert[]> {
  return apiFetch(`/v1/security/alerts?days=${days}`);
}

export interface ROISummary {
  total_input_tokens: number;
  total_saved: number;
  estimated_cost_saved: number;
  event_count: number;
  project_count: number;
  days_tracked: number;
  savings_pct: number;
  monthly: { month: string; input_tokens: number; tokens_saved: number; event_count: number }[];
}

export function fetchROISummary(days: number = 90): Promise<ROISummary> {
  return apiFetch(`/v1/roi?days=${days}`);
}

export function exportCSVUrl(days: number = 30): string {
  return `${API_URL}/v1/export/csv?days=${days}`;
}

export interface BillingInfo {
  tenant_id: string;
  plan: string;
  status: string;
}

export function fetchBillingStatus(): Promise<BillingInfo> {
  return apiFetch("/v1/billing/status");
}

export async function createCheckout(): Promise<string> {
  const res = await fetch(`${API_URL}/v1/billing/checkout`, {
    method: "POST",
    headers: { "X-Tenant-ID": TENANT_ID },
  });
  if (!res.ok) throw new Error(`Checkout failed: ${res.status}`);
  const data = await res.json();
  return data.checkout_url;
}

export function shortProjectName(projectDir: string): string {
  const parts = projectDir.split(/[/\\]/).filter(Boolean);
  return parts.length > 0 ? parts[parts.length - 1] : projectDir;
}

"use client";

import { useEffect, useState } from "react";
import {
  Card,
  CardContent,
  CardDescription,
  CardHeader,
  CardTitle,
} from "@/components/ui/card";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { DateRangeSelector } from "@/components/date-range-selector";
import {
  fetchROISummary,
  exportCSVUrl,
  formatTokens,
  type ROISummary,
} from "@/lib/api";

export default function ROIPage() {
  const [summary, setSummary] = useState<ROISummary | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [loading, setLoading] = useState(true);
  const [days, setDays] = useState(90);
  const [costPerDev, setCostPerDev] = useState(12);
  const [teamSize, setTeamSize] = useState(5);

  useEffect(() => {
    setLoading(true);
    fetchROISummary(days)
      .then(setSummary)
      .catch((e) => setError(e.message))
      .finally(() => setLoading(false));
  }, [days]);

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <p className="text-muted-foreground">Loading...</p>
      </div>
    );
  }

  if (error || !summary) {
    return (
      <div className="space-y-4">
        <h1 className="text-2xl font-bold">ROI Calculator</h1>
        <Card>
          <CardContent className="pt-6">
            <p className="text-muted-foreground">
              Could not load ROI data. Make sure the API is running.
            </p>
          </CardContent>
        </Card>
      </div>
    );
  }

  const monthlyCost = costPerDev * teamSize;
  const periodMonths = Math.ceil(days / 30);
  const totalCost = monthlyCost * periodMonths;
  const roi =
    totalCost > 0
      ? ((summary.estimated_cost_saved - totalCost) / totalCost) * 100
      : 0;

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <h1 className="text-2xl font-bold">ROI Calculator</h1>
        <div className="flex items-center gap-2">
          <DateRangeSelector value={days} onChange={setDays} />
          <a href={exportCSVUrl(days)} download>
            <Button variant="outline" size="sm">
              Export CSV
            </Button>
          </a>
        </div>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <MetricCard
          title="Tokens Saved"
          value={formatTokens(summary.total_saved)}
          description={`across ${summary.project_count} projects`}
        />
        <MetricCard
          title="Est. Cost Saved"
          value={`$${summary.estimated_cost_saved.toFixed(2)}`}
          description={`${summary.savings_pct.toFixed(1)}% savings rate`}
        />
        <MetricCard
          title="CODEFLOW Cost"
          value={`$${totalCost}`}
          description={`$${costPerDev}/dev × ${teamSize} devs × ${periodMonths}mo`}
        />
        <MetricCard
          title="ROI"
          value={`${roi > 0 ? "+" : ""}${roi.toFixed(0)}%`}
          description={
            roi > 0 ? "net positive return" : "building toward breakeven"
          }
        />
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Adjust Assumptions</CardTitle>
        </CardHeader>
        <CardContent className="flex gap-8">
          <div>
            <label className="text-sm text-muted-foreground">
              Cost per dev/mo
            </label>
            <input
              type="number"
              value={costPerDev}
              onChange={(e) => setCostPerDev(Number(e.target.value))}
              className="block mt-1 w-24 border rounded px-2 py-1 text-sm"
            />
          </div>
          <div>
            <label className="text-sm text-muted-foreground">Team size</label>
            <input
              type="number"
              value={teamSize}
              onChange={(e) => setTeamSize(Number(e.target.value))}
              className="block mt-1 w-24 border rounded px-2 py-1 text-sm"
            />
          </div>
        </CardContent>
      </Card>

      {summary.monthly && summary.monthly.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Monthly Breakdown</CardTitle>
            <CardDescription>Savings by month</CardDescription>
          </CardHeader>
          <CardContent>
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Month</TableHead>
                  <TableHead className="text-right">Input Tokens</TableHead>
                  <TableHead className="text-right">Tokens Saved</TableHead>
                  <TableHead className="text-right">Events</TableHead>
                  <TableHead className="text-right">Est. Saved</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {summary.monthly.map((m) => (
                  <TableRow key={m.month}>
                    <TableCell className="font-medium">{m.month}</TableCell>
                    <TableCell className="text-right">
                      {formatTokens(m.input_tokens)}
                    </TableCell>
                    <TableCell className="text-right">
                      {formatTokens(m.tokens_saved)}
                    </TableCell>
                    <TableCell className="text-right">
                      {m.event_count}
                    </TableCell>
                    <TableCell className="text-right">
                      ${((m.tokens_saved / 1000) * 0.003).toFixed(2)}
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

function MetricCard({
  title,
  value,
  description,
}: {
  title: string;
  value: string;
  description: string;
}) {
  return (
    <Card>
      <CardHeader className="pb-2">
        <CardDescription>{title}</CardDescription>
        <CardTitle className="text-3xl">{value}</CardTitle>
      </CardHeader>
      <CardContent>
        <p className="text-sm text-muted-foreground">{description}</p>
      </CardContent>
    </Card>
  );
}

