222	mod tests {
223	    use codeflow_core::dedup::DedupCache;
224	    use codeflow_core::filter::{
225	        CommandMatch, FilterConfig, FilterPipeline, StripLinesRule,
226	    };
227	    use tempfile::TempDir;
228	
229	    fn make_pipeline_with_strip(command: &str, strip_pattern: &str) -> FilterPipeline {
230	        let mut pipeline = FilterPipeline::new();
231	        pipeline.add_config(FilterConfig {
232	            command: CommandMatch {
233	                name: command.to_string(),
234	                args_contain: vec![],
235	            },
236	            strip_ansi: Some(false),
237	            replace: vec![],
238	            match_output: None,
239	            strip_lines: vec![StripLinesRule {
240	                pattern: strip_pattern.to_string(),
241	            }],
242	            truncate_lines: None,
243	            head_tail: None,
244	            max_lines: None,
245	            on_empty: None,
246	        });
247	        pipeline
248	    }
249	
250	    // --- filter-only path ---
251	
252	    #[test]
253	    fn test_filter_reduces_output() {
254	        // Pipeline strips "Downloading" lines — noisy cargo-like output should shrink
255	        let pipeline = make_pipeline_with_strip("cargo", r"^Downloading");
256	        let raw = "Downloading foo v1.0\nDownloading bar v2.0\nCompiling mylib v0.1\nFinished in 3.2s";
257	        let result = pipeline.apply("cargo", &[], raw);
258	        assert!(result.filter_applied);
259	        assert!(
260	            result.output_len < result.input_len,
261	            "filtered output ({}) should be smaller than input ({})",
262	            result.output_len,
263	            result.input_len
264	        );
265	        assert!(!result.output.contains("Downloading"));
266	        assert!(result.output.contains("Compiling"));
267	    }
268	
269	    #[test]
270	    fn test_filter_passthrough_when_no_match() {
271	        // Pipeline exists for "cargo" but we apply it to "npm" — passthrough
272	        let pipeline = make_pipeline_with_strip("cargo", r"^Downloading");
273	        let raw = "some output that would normally be filtered";
274	        let result = pipeline.apply("npm", &[], raw);
275	        assert!(!result.filter_applied);
276	        assert_eq!(result.output, raw);
277	    }
278	
279	    // --- fail-open: empty pipeline passes through ---
280	
281	    #[test]
282	    fn test_empty_pipeline_passthrough() {
283	        // When filter config is missing/broken, FilterPipeline::new() is used
284	        // which is exactly what compress() falls back to on error.
285	        let pipeline = FilterPipeline::new();
286	        let raw = "important output that must not be lost";
287	        let result = pipeline.apply("anything", &[], raw);
288	        assert!(!result.filter_applied, "empty pipeline should not filter");
289	        assert_eq!(result.output, raw, "output should be unchanged");
290	        assert_eq!(result.input_len, result.output_len);
291	    }
292	
293	    // --- dedup cache within compress pipeline ---
294	
295	    #[test]
296	    fn test_dedup_cache_miss_on_first_lookup() {
297	        let dir = TempDir::new().unwrap();
298	        let db_path = dir.path().join("test.db");
299	        let cache = DedupCache::open(&db_path, "wrap-test-session").unwrap();
300	
301	        let result = cache.lookup("cmd:cargo:build", 0, "build output content").unwrap();
302	        assert!(!result.cache_hit);
303	        assert_eq!(result.tokens_saved, 0);
304	    }
305	
306	    #[test]
307	    fn test_dedup_cache_hit_on_second_lookup_same_session() {
308	        let dir = TempDir::new().unwrap();
309	        let db_path = dir.path().join("test.db");
310	        let cache = DedupCache::open(&db_path, "wrap-test-session").unwrap();
311	
312	        let content = "build finished successfully\nerror count: 0";
313	        // First lookup: miss, stores entry
314	        let r1 = cache.lookup("cmd:cargo:build", 0, content).unwrap();
315	        assert!(!r1.cache_hit);
316	
317	        // Second lookup with same mtime=0 and same content: hit
318	        let r2 = cache.lookup("cmd:cargo:build", 0, content).unwrap();
319	        assert!(r2.cache_hit);
320	        assert!(r2.tokens_saved > 0);
321	        assert!(r2.summary.is_some());
322	    }
323	
324	    #[test]
325	    fn test_dedup_cache_different_sessions_no_hit() {
326	        let dir = TempDir::new().unwrap();
327	        let db_path = dir.path().join("test.db");
328	
329	        let cache1 = DedupCache::open(&db_path, "session-a").unwrap();
330	        cache1.lookup("cmd:git:status", 0, "nothing to commit").unwrap();
331	        drop(cache1);
332	
333	        // New session — same content, same mtime, but different session_id → miss
334	        let cache2 = DedupCache::open(&db_path, "session-b").unwrap();
335	        let r = cache2.lookup("cmd:git:status", 0, "nothing to commit").unwrap();
336	        assert!(!r.cache_hit, "cross-session lookup must not hit");
337	    }
338	}
