#[cfg(test)]
mod tests {
    use codeflow_core::dedup::DedupCache;
    use codeflow_core::filter::{
        CommandMatch, FilterConfig, FilterPipeline, StripLinesRule,
    };
    use tempfile::TempDir;

    fn make_pipeline_with_strip(command: &str, strip_pattern: &str) -> FilterPipeline {
        let mut pipeline = FilterPipeline::new();
        pipeline.add_config(FilterConfig {
            command: CommandMatch {
                name: command.to_string(),
                args_contain: vec![],
            },
            strip_ansi: Some(false),
            replace: vec![],
            match_output: None,
            strip_lines: vec![StripLinesRule {
                pattern: strip_pattern.to_string(),
            }],
            truncate_lines: None,
            head_tail: None,
            max_lines: None,
            on_empty: None,
        });
        pipeline
    }

    // --- filter-only path ---

    #[test]
    fn test_filter_reduces_output() {
        // Pipeline strips "Downloading" lines — noisy cargo-like output should shrink
        let pipeline = make_pipeline_with_strip("cargo", r"^Downloading");
        let raw = "Downloading foo v1.0\nDownloading bar v2.0\nCompiling mylib v0.1\nFinished in 3.2s";
        let result = pipeline.apply("cargo", &[], raw);
        assert!(result.filter_applied);
        assert!(
            result.output_len < result.input_len,
            "filtered output ({}) should be smaller than input ({})",
            result.output_len,
            result.input_len
        );
        assert!(!result.output.contains("Downloading"));
        assert!(result.output.contains("Compiling"));
    }

    #[test]
    fn test_filter_passthrough_when_no_match() {
        // Pipeline exists for "cargo" but we apply it to "npm" — passthrough
        let pipeline = make_pipeline_with_strip("cargo", r"^Downloading");
        let raw = "some output that would normally be filtered";
        let result = pipeline.apply("npm", &[], raw);
        assert!(!result.filter_applied);
        assert_eq!(result.output, raw);
    }

    // --- fail-open: empty pipeline passes through ---

    #[test]
    fn test_empty_pipeline_passthrough() {
        // When filter config is missing/broken, FilterPipeline::new() is used
        // which is exactly what compress() falls back to on error.
        let pipeline = FilterPipeline::new();
        let raw = "important output that must not be lost";
        let result = pipeline.apply("anything", &[], raw);
        assert!(!result.filter_applied, "empty pipeline should not filter");
        assert_eq!(result.output, raw, "output should be unchanged");
        assert_eq!(result.input_len, result.output_len);
    }

    // --- dedup cache within compress pipeline ---

    #[test]
    fn test_dedup_cache_miss_on_first_lookup() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("test.db");
        let cache = DedupCache::open(&db_path, "wrap-test-session").unwrap();

        let result = cache.lookup("cmd:cargo:build", 0, "build output content").unwrap();
        assert!(!result.cache_hit);
        assert_eq!(result.tokens_saved, 0);
    }

    #[test]
    fn test_dedup_cache_hit_on_second_lookup_same_session() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("test.db");
        let cache = DedupCache::open(&db_path, "wrap-test-session").unwrap();

        let content = "build finished successfully\nerror count: 0";
        // First lookup: miss, stores entry
        let r1 = cache.lookup("cmd:cargo:build", 0, content).unwrap();
        assert!(!r1.cache_hit);

        // Second lookup with same mtime=0 and same content: hit
        let r2 = cache.lookup("cmd:cargo:build", 0, content).unwrap();
        assert!(r2.cache_hit);
        assert!(r2.tokens_saved > 0);
        assert!(r2.summary.is_some());
    }

    #[test]
    fn test_dedup_cache_different_sessions_no_hit() {
        let dir = TempDir::new().unwrap();
        let db_path = dir.path().join("test.db");

        let cache1 = DedupCache::open(&db_path, "session-a").unwrap();
        cache1.lookup("cmd:git:status", 0, "nothing to commit").unwrap();
        drop(cache1);

        // New session — same content, same mtime, but different session_id → miss
        let cache2 = DedupCache::open(&db_path, "session-b").unwrap();
        let r = cache2.lookup("cmd:git:status", 0, "nothing to commit").unwrap();
        assert!(!r.cache_hit, "cross-session lookup must not hit");
    }
}

package main

import (
	"bytes"
	"compress/gzip"
	"fmt"
	"io"
	"net/http"
	"time"

	pb "github.com/codeflow-dev/codeflow/cloud/proto"
	"google.golang.org/protobuf/proto"
)

func main() {
	now := time.Now()
	events := make([]*pb.Event, 0, 50)

	commands := []struct {
		cmd    string
		filter string
		input  uint64
		saved  uint64
	}{
		{"git diff", "git-diff", 8000, 3200},
		{"git status", "git-status", 2000, 1400},
		{"cargo test", "cargo-test", 12000, 5400},
		{"npm test", "npm-test", 6000, 2100},
		{"tsc", "tsc", 3000, 900},
		{"cargo build", "cargo-build", 15000, 7500},
		{"eslint .", "eslint", 4000, 1600},
		{"pytest", "pytest", 5000, 1750},
		{"go test ./...", "go-test", 9000, 3600},
		{"docker logs app", "docker-logs", 7000, 4200},
	}

	projects := []string{
		"/home/user/codeflow",
		"/home/user/dashboard",
		"/home/user/api-server",
	}

	id := 0
	for day := 0; day < 14; day++ {
		ts := now.AddDate(0, 0, -day)
		for _, proj := range projects {
			for _, cmd := range commands {
				id++
				events = append(events, &pb.Event{
					Id:          fmt.Sprintf("seed-%d", id),
					TimestampMs: ts.UnixMilli(),
					SessionId:   fmt.Sprintf("sess-%d-%d", day, id%5),
					ProjectDir:  proj,
					Command:     cmd.cmd,
					Compression: &pb.CompressionEvent{
						InputBytes:  cmd.input * 4,
						OutputBytes: (cmd.input - cmd.saved) * 4,
						InputTokens: cmd.input,
						OutputTokens: cmd.input - cmd.saved,
						TokensSaved: cmd.saved,
						FilterName:  cmd.filter,
						LatencyMs:   1.5,
					},
				})

				if day%3 == 0 {
					id++
					events = append(events, &pb.Event{
						Id:          fmt.Sprintf("seed-%d", id),
						TimestampMs: ts.UnixMilli(),
						SessionId:   fmt.Sprintf("sess-%d-%d", day, id%5),
						ProjectDir:  proj,
						Command:     cmd.cmd,
						Dedup: &pb.DedupEvent{
							ContentHash: fmt.Sprintf("hash-%d", id),
							CacheHit:    true,
							TokensSaved: cmd.saved / 2,
							LatencyMs:   0.3,
						},
					})
				}
			}
		}
	}

	batch := &pb.EventBatch{
		CliVersion: "0.1.0-seed",
		MachineId:  "seed-machine",
		Events:     events,
	}

	data, err := proto.Marshal(batch)
	if err != nil {
		panic(err)
	}

	var buf bytes.Buffer
	gz := gzip.NewWriter(&buf)
	gz.Write(data)
	gz.Close()

	fmt.Printf("Seeding %d events (%d bytes proto, %d bytes gzipped)...\n",
		len(events), len(data), buf.Len())

	req, _ := http.NewRequest("POST", "http://localhost:8080/v1/events", &buf)
	req.Header.Set("Content-Type", "application/x-protobuf")
	req.Header.Set("Content-Encoding", "gzip")
	req.Header.Set("X-Tenant-ID", "demo-tenant")

	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()

	body, _ := io.ReadAll(resp.Body)
	fmt.Printf("Response: %d %s\n", resp.StatusCode, string(body))
}

package main

import (
	"context"
	"log/slog"
	"net/http"
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/codeflow-dev/codeflow/cloud/internal/api"
	"github.com/codeflow-dev/codeflow/cloud/internal/clickhouse"
	"github.com/codeflow-dev/codeflow/cloud/internal/natsutil"
)

func main() {
	logger := slog.New(slog.NewJSONHandler(os.Stdout, &slog.HandlerOptions{Level: slog.LevelInfo}))
	slog.SetDefault(logger)

	chDSN := envOr("CLICKHOUSE_DSN", "clickhouse://localhost:9000/codeflow")
	listenAddr := envOr("LISTEN_ADDR", ":8080")
	natsURL := os.Getenv("NATS_URL")

	ch, err := clickhouse.New(chDSN)
	if err != nil {
		slog.Error("failed to connect to clickhouse", "error", err)
		os.Exit(1)
	}
	defer ch.Close()
	slog.Info("connected to clickhouse", "dsn", chDSN)

	var opts []api.RouterOption

	if natsURL != "" {
		pub, err := natsutil.NewPublisher(natsURL)
		if err != nil {
			slog.Error("failed to connect to nats", "error", err)
			os.Exit(1)
		}
		defer pub.Close()

		if err := pub.EnsureStream(context.Background()); err != nil {
			slog.Error("failed to ensure nats stream", "error", err)
			os.Exit(1)
		}

		opts = append(opts, api.WithPublisher(pub))
		slog.Info("nats enabled — events will be published to jetstream", "url", natsURL)
	} else {
		slog.Info("nats not configured — events will be inserted directly to clickhouse")
	}

	handler := api.NewRouter(ch, logger, opts...)

	srv := &http.Server{
		Addr:         listenAddr,
		Handler:      handler,
		ReadTimeout:  30 * time.Second,
		WriteTimeout: 30 * time.Second,
		IdleTimeout:  120 * time.Second,
	}

	go func() {
		slog.Info("ingest API listening", "addr", listenAddr)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			slog.Error("server error", "error", err)
			os.Exit(1)
		}
	}()

	quit := make(chan os.Signal, 1)
	signal.Notify(quit, syscall.SIGINT, syscall.SIGTERM)
	<-quit

	slog.Info("shutting down...")
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	if err := srv.Shutdown(ctx); err != nil {
		slog.Error("shutdown error", "error", err)
	}
	slog.Info("server stopped")
}

func envOr(key, fallback string) string {
	if v := os.Getenv(key); v != "" {
		return v
	}
	return fallback
}

